// Dimensioned, interactive 3D concept geometry. No manufacturer CAD is supplied yet.
export function installVanityExplorer({products,styles}){
const esc=s=>String(s).replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('"','&quot;');let active=null,returnFocus=null,yaw=-.55,pitch=.23,zoom=1,opened=false,cutaway=false,styled=true,drag=null,engine=null,enginePromise=null;
const dialog=document.createElement('dialog');dialog.className='v-explorer';dialog.setAttribute('aria-labelledby','v-explorer-title');dialog.innerHTML=`<header class="v-explorer-head"><div><span class="eyebrow">Know the cabinet before you choose it</span><h2 id="v-explorer-title">Explore your vanity</h2></div><button type="button" class="v-explorer-close" aria-label="Close cabinet explorer">×</button></header><div class="v-explorer-tabs" role="tablist" aria-label="Cabinet explorer"><button type="button" role="tab" id="v-tab-model" aria-controls="v-panel-model" aria-selected="true" tabindex="0">Explore in 3D</button><button type="button" role="tab" id="v-tab-video" aria-controls="v-panel-video" aria-selected="false" tabindex="-1">Watch assembly</button></div><section id="v-panel-model" role="tabpanel" aria-labelledby="v-tab-model"><div class="v-explorer-layout"><div><div class="v-3d-stage"><canvas id="v-3d-canvas" width="1100" height="720" tabindex="0" role="img" aria-label="Interactive 3D cabinet. Drag to rotate or use arrow keys. Plus and minus keys zoom."></canvas><span class="v-orbit-hint">Drag to rotate · arrow keys work too</span><span class="v-render-status" role="status">Loading product render…</span></div><div class="v-3d-controls"><button type="button" data-v-angle="front">Front</button><button type="button" data-v-angle="rear">Rear</button><button type="button" id="v-open-fronts" aria-pressed="false">Open doors & drawers</button><button type="button" id="v-cutaway" aria-pressed="false">Inside view</button><button type="button" id="v-style-top" aria-pressed="true">Style with top & basin</button><button type="button" data-v-zoom="-1" aria-label="Zoom cabinet out">−</button><button type="button" data-v-zoom="1" aria-label="Zoom cabinet in">+</button><button type="button" id="v-reset-model">Reset view</button></div></div><aside id="v-3d-specs"></aside></div><p class="v-3d-disclosure">Sample 3D render based on the collection image and selected cabinet dimensions. Final construction details require supplier specifications. The optional top, basin and faucet are styling references and are not included in the cabinet price.</p></section><section id="v-panel-video" role="tabpanel" aria-labelledby="v-tab-video" hidden><div class="v-video-explorer"><div><div id="v-reference-player" class="v-reference-player"></div><p class="caption" id="v-reference-credit"></p><a class="textlink" id="v-reference-open" target="_blank" rel="noopener">Open on YouTube ↗</a></div><aside><span class="eyebrow">A manufacturer demonstration</span><h3>See the sequence.<br>Understand the parts.</h3><p id="v-reference-scope"></p><ul><li>Watch how the cabinet box is brought together.</li><li>Look for the door or drawer assembly sequence.</li><li>Use your final model’s hardware list and manual at the workbench.</li></ul><p class="caption">Independent reference from RTA Cabinet Store. This is not a Kabby Home product video or a model-specific instruction for this sample SKU. The presenter is not identified here as a designer.</p><a class="textlink" href="https://www.rtacabinetstore.com/resources/assembly/32/primary-white/" target="_blank" rel="noopener">Manufacturer’s full assembly library ↗</a><a class="btn outline" href="/kabbyhome/assets/vanities/kabbie-vanity-rta-guide.pdf" download>Download our preparation checklist ↓</a></aside></div></section>`;document.body.append(dialog);
const find=s=>dialog.querySelector(s),canvas=find('canvas'),W=1100,H=720;const tabButtons=[find('#v-tab-model'),find('#v-tab-video')];
function tab(name){const video=name==='video';tabButtons.forEach((b,i)=>{b.setAttribute('aria-selected',String(i===(video?1:0)));b.tabIndex=i===(video?1:0)?0:-1;});find('#v-panel-model').hidden=video;find('#v-panel-video').hidden=!video;if(video)renderVideo();else{find('#v-reference-player').innerHTML='';draw();}}
function ref(){return active.width<=30||active.width>=60?{id:'q20fu7xHLCA',title:'V30 Assembly',model:'30-inch double-door vanity'}:{id:'iB26eN5BkVw',title:'VSBDR36 Assembly',model:'36-inch vanity with a drawer bank'};}
function renderVideo(){const v=ref();find('#v-reference-player').innerHTML=`<div class="v-reference-cover"><span class="eyebrow">RTA Cabinet Store / official assembly library</span><h3>${v.title}</h3><p>${v.model}</p><button type="button" class="btn" id="v-load-reference">Play manufacturer demonstration ▶</button><small>Loads the manufacturer’s YouTube video when you press play.</small></div>`;find('#v-reference-credit').textContent='RTA Cabinet Store · '+v.title+' · '+v.model;find('#v-reference-open').href='https://www.youtube.com/watch?v='+v.id;find('#v-reference-scope').textContent=`This video demonstrates a ${v.model}. ${active.style==='floating'?'It shows a floor-standing reference cabinet; it does not cover the structural fixing required for your floating concept.':active.width>=60?'It does not demonstrate the complete double-sink cabinet selected here.':'Use it to understand the general sequence, then follow the manual supplied with your actual cabinet.'}`;find('#v-load-reference').onclick=()=>{find('#v-reference-player').innerHTML=`<iframe title="RTA Cabinet Store: ${v.title} manufacturer demonstration" src="https://www.youtube-nocookie.com/embed/${v.id}?autoplay=1&rel=0" allow="autoplay; encrypted-media; picture-in-picture" allowfullscreen referrerpolicy="strict-origin-when-cross-origin"></iframe>`;};}
function specs(){const s=styles.find(s=>s.id===active.style);find('#v-explorer-title').textContent=active.name+' · '+s.finish;find('#v-3d-specs').innerHTML=`<span class="eyebrow">${active.id}</span><h3>A closer look<br>at your cabinet.</h3><dl><div><dt>Width</dt><dd>${active.width}″</dd></div><div><dt>Depth</dt><dd>${active.depth}″</dd></div><div><dt>Cabinet height</dt><dd>${active.height}″</dd></div><div><dt>Door profile</dt><dd>${s.profile}</dd></div><div><dt>Installation type</dt><dd>${s.mount}</dd></div><div><dt>Layout</dt><dd>${active.orientation}</dd></div></dl><p>Rotate to see the cabinet’s proportions. Open the fronts to explore storage, or switch to the inside view to see the proposed sink bay.</p><p class="caption">Switch the styled top and basin off to inspect the cabinet alone. Sink, top, faucet and hardware shown are visual references; final inclusions require a confirmed quote.</p><figure class="v-render-reference"><img src="/kabbyhome/assets/vanities/${s.image}" alt="${s.name} collection image used as the sample render reference"><figcaption>Collection image · visual reference</figcaption></figure><button type="button" class="btn" id="v-explorer-watch">Watch assembly →</button>`;find('#v-explorer-watch').onclick=()=>tab('video');}
function open(id,view='model',trigger=null){active=products.find(p=>p.id===id);if(!active)return;returnFocus=trigger||document.activeElement;yaw=-.55;pitch=.23;zoom=1;opened=false;cutaway=false;styled=true;find('#v-style-top').setAttribute('aria-pressed','true');find('#v-open-fronts').setAttribute('aria-pressed','false');find('#v-cutaway').setAttribute('aria-pressed','false');specs();dialog.showModal();document.body.classList.add('v-explorer-open');tab(view);}
function close(){find('#v-reference-player').innerHTML='';dialog.close();document.body.classList.remove('v-explorer-open');returnFocus?.focus();}
dialog.addEventListener('cancel',e=>{e.preventDefault();close();});find('.v-explorer-close').onclick=close;dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)close();}});
tabButtons[0].onclick=()=>tab('model');tabButtons[1].onclick=()=>tab('video');tabButtons.forEach((b,i)=>b.onkeydown=e=>{if(e.key==='ArrowRight'||e.key==='ArrowLeft'){e.preventDefault();tab(i===0?'video':'model');tabButtons[1-i].focus();}});
find('#v-open-fronts').onclick=()=>{opened=!opened;find('#v-open-fronts').setAttribute('aria-pressed',String(opened));draw();};find('#v-cutaway').onclick=()=>{cutaway=!cutaway;find('#v-cutaway').setAttribute('aria-pressed',String(cutaway));if(cutaway){pitch=.45;opened=true;styled=false;find('#v-style-top').setAttribute('aria-pressed','false');find('#v-open-fronts').setAttribute('aria-pressed','true');}draw();};find('#v-style-top').onclick=()=>{styled=!styled;find('#v-style-top').setAttribute('aria-pressed',String(styled));if(styled&&cutaway){cutaway=false;find('#v-cutaway').setAttribute('aria-pressed','false');}draw();};find('#v-reset-model').onclick=()=>{yaw=-.55;pitch=.23;zoom=1;opened=false;cutaway=false;styled=true;find('#v-style-top').setAttribute('aria-pressed','true');find('#v-open-fronts').setAttribute('aria-pressed','false');find('#v-cutaway').setAttribute('aria-pressed','false');draw();};dialog.querySelectorAll('[data-v-angle]').forEach(b=>b.onclick=()=>{yaw=b.dataset.vAngle==='front'?0:Math.PI;pitch=.16;draw();});dialog.querySelectorAll('[data-v-zoom]').forEach(b=>b.onclick=()=>{zoom=Math.max(.7,Math.min(1.55,zoom+Number(b.dataset.vZoom)*.1));draw();});
canvas.addEventListener('pointerdown',e=>{drag={x:e.clientX,y:e.clientY};canvas.setPointerCapture(e.pointerId);canvas.style.cursor='grabbing';});canvas.addEventListener('pointermove',e=>{if(!drag)return;yaw+=(e.clientX-drag.x)*.009;pitch=Math.max(-.2,Math.min(.8,pitch+(e.clientY-drag.y)*.006));drag={x:e.clientX,y:e.clientY};draw();});function release(){drag=null;canvas.style.cursor='grab';}canvas.addEventListener('pointerup',release);canvas.addEventListener('pointercancel',release);canvas.onkeydown=e=>{if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown','+','=','-'].includes(e.key)){e.preventDefault();if(e.key==='ArrowLeft')yaw-=.16;if(e.key==='ArrowRight')yaw+=.16;if(e.key==='ArrowUp')pitch=Math.min(.8,pitch+.08);if(e.key==='ArrowDown')pitch=Math.max(-.2,pitch-.08);if(e.key==='+'||e.key==='=')zoom=Math.min(1.55,zoom+.1);if(e.key==='-')zoom=Math.max(.7,zoom-.1);draw();}};
function draw(){if(!active)return;const status=find('.v-render-status');if(!engine){status.hidden=false;if(!enginePromise){enginePromise=import('./vanity-pbr.js').then(m=>{engine=m.createVanityRenderer(canvas);status.hidden=true;draw();}).catch(error=>{console.error('Vanity renderer:',error);status.textContent='The 3D renderer could not start. Use a WebGL-capable browser to explore the cabinet.';canvas.dataset.renderError='true';});}return;}status.hidden=true;engine.setProduct(active,styles.find(s=>s.id===active.style));engine.update({yaw,pitch,zoom,opened,cutaway,styled});}

return {open};
}
